129		}
130	
131		if err := s.Start(); err != nil {
132			t.Fatalf("failed to start: %v", err)
133		}
134	
135		time.Sleep(1500 * time.Millisecond)
136	
137		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
138		defer cancel()
139	
140		if err := s.Stop(ctx); err != nil {
141			t.Fatalf("failed to stop: %v", err)
142		}
143	
144		logMu.Lock()
145		defer logMu.Unlock()
146	
147		// Should have at least one start and one completion log
148		hasStart := false
149		hasCompletion := false
150		for _, log := range executionLog {
151			if strings.Contains(log, "Job started") {
152				hasStart = true
153			}
154			if strings.Contains(log, "Job completed") {
155				hasCompletion = true
156			}
157		}
158	
159		if !hasStart {
160			t.Error("expected job start log")
161		}
162		if !hasCompletion {
163			t.Error("expected job completion log")
164		}
